  isOpen: boolean;
  book: Book;
  onClose: () => void;
  onUpdateBookSidecar: (bookId: string, updatedSidecarMd: string) => void;
}

export const NovelUpdatesModal: React.FC<NovelUpdatesModalProps> = ({
  isOpen,
  book,
  onClose,
  onUpdateBookSidecar,
}) => {
  const [searchTitle, setSearchTitle] = useState(book.title);
  const [scrapedData, setScrapedData] = useState(scrapeNovelUpdatesMetadata(book.title));
  const [applied, setApplied] = useState(false);

  if (!isOpen) return null;

  const handleScrape = () => {
    const data = scrapeNovelUpdatesMetadata(searchTitle);
    setScrapedData(data);
  };

  const handleApplyToSidecar = () => {
    let md = book.sidecarMarkdown;

    // Inject associated names, rating, and tags into sidecar
    if (!md.includes('novel_updates:')) {
      const nuBlock = `novel_updates:\n  rating: ${scrapedData.rating}\n  publisher: "${scrapedData.originalPublisher}"\n  status: "${scrapedData.statusInCOO}"\n  url: "${scrapedData.novelUpdatesUrl}"\n`;
      md = md.replace(/---\n/, `---\n${nuBlock}`);
    }

    const tagsLine = `tags: [${scrapedData.tags.map(t => `"${t}"`).join(', ')}]`;
    if (md.includes('tags:')) {
      md = md.replace(/tags:\s*\[.*?\]/, tagsLine);
    } else {
      md += `\n${tagsLine}\n`;
    }

    if (!md.includes('#novel-updates')) {
      md += `\n- **[NovelUpdates Metadata]** *Scraped from NovelUpdates.com &bull; Rating: ${scrapedData.rating}/5.0 &bull; Publisher: ${scrapedData.originalPublisher} (${scrapedData.statusInCOO})*\n`;
    }

    onUpdateBookSidecar(book.id, md);
    setApplied(true);
    setTimeout(() => {
      setApplied(false);
      onClose();
    }
