"export interface BookmarkletTool {
  id: string;
  name: string;
  targetSite: string;
  icon: string;
  description: string;
  bookmarkletJs: string;
}

export function getAppHostUrl(): string {
  if (typeof window !== 'undefined') {
    return window.location.origin;
  }
  return 'http://localhost:5175';
}

export function generateNovelUpdatesBookmarklet(): string {
  const host = getAppHostUrl();
  const code = `(function(){
    const title = document.querySelector('.seriestitlenew, h1.entry-title, .series-title')?.innerText?.trim() || document.title.replace(' - Novel Updates', '');
    const tags = Array.from(document.querySelectorAll('#showtags a, a.genre')).map(e => e.innerText.trim());
    const rating = document.querySelector('.uvote')?.innerText?.trim() || '4.5';
    const targetUrl = '${host}/?import_novel=' + encodeURIComponent(title) + '&tags=' + encodeURIComponent(tags.join(',')) + '&rating=' + encodeURIComponent(rating);
    window.open(targetUrl, '_blank');
  })();`;
  return `javascript:${encodeURIComponent(code.replace(/\s+/g, ' '))}`;
}

export function generateGoodreadsBookmarklet(): string {
  const host = getAppHostUrl();
  const code = `(function(){
    const singleTitle = document.querySelector('#bookTitle, h1[data-testid="bookTitle"]')?.innerText?.trim();
    let titles = [];
    if (singleTitle) {
      titles.push(singleTitle);
    } else {
      titles = Array.from(document.querySelectorAll('.bookTitle, a.bookTitle span')).map(e => e.innerText.trim()).filter(Boolean);
    }
    if (titles.length === 0) titles.push(document.title.replace(' | Goodreads', ''));
    const targetUrl = '${host}/?import_goodreads=' + encodeURIComponent(JSON.stringify(titles));
    window.open(targetUrl, '_blank');
  })();`;
  return `javascript:${encodeURIComponent(code.replace(/\s+/g, ' '))}`;
}

