  } catch (err) {
    console.warn('Failed to load monetization settings:', err);
  }
  return DEFAULT_MONETIZATION_SETTINGS;
}

export function saveMonetizationSettings(settings: MonetizationSettings): void {
  try {
    localStorage.setItem('lc_md_monetization_settings', JSON.stringify(settings));
  } catch (err) {
    console.warn('Failed to save monetization settings:', err);
  }
}

