"import React, { useState, useRef } from 'react';
import type { Book } from '../types/resonance';
import type { ScannedCardItem } from '../plugins/cardScannerPlugin';
import { scanPageOfCardsImage, convertScannedCardsToVaultItems } from '../plugins/cardScannerPlugin';
import { X, Camera, Scan, Sparkles, Check, ShieldCheck, Upload } from 'lucide-react';

interface CardScannerModalProps {
  isOpen: boolean;
  onClose: () => void;
  onAutoGenerateVaultItems: (newBooks: Book[]) => void;
}

export const CardScannerModal: React.FC<CardScannerModalProps> = ({
  isOpen,
  onClose,
  onAutoGenerateVaultItems,
}) => {
  const [isScanning, setIsScanning] = useState(false);
  const [scannedResults, setScannedResults] = useState<ScannedCardItem[] | null>(null);
  const [generatedSuccess, setGeneratedSuccess] = useState(false);
  const [photoUrl, setPhotoUrl] = useState<string | null>(null);
  const [photoName, setPhotoName] = useState<string | null>(null);
  const fileInputRef = useRef<HTMLInputElement | null>(null);

  if (!isOpen) return null;

  const handlePhotoFileChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (file) {
      setPhotoName(file.name);
      const url = URL.createObjectURL(file);
      setPhotoUrl(url);
      handleSimulateUpload(file.name);
    }
  };

  const handleSimulateUpload = (fileName?: string) => {
    setIsScanning(true);
    setScannedResults(null);

    setTimeout(() => {
      const results = scanPageOfCardsImage(fileName || 'binder_sheet_9cards.png');
      setScannedResults(results);
      setIsScanning(false);
    }, 1200);
  };"

